SELECT 'core-2026-09-v4','comparatives-and-superlatives','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"comparatives-and-superlatives","title":"Comparatives and superlatives","level":"A2","order":23,"summary":"Compare two things, identify an extreme in a group, and express equality.","learningGoals":["Comparing two","Comparing a group","Equal degree"],"guidance":"Read the short rules and examples, then complete a 20-question session. Use feedback to explain each choice. Revisit the skill you missed before trying again.","rules":[{"title":"Comparing two","explanation":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","examples":["This route is shorter than that one.","The new seat is more comfortable."]},{"title":"Comparing a group","explanation":"Use the plus a superlative: often -est or most plus the adjective. Good becomes better/best; bad becomes worse/worst.","examples":["This is the safest path.","That was the best result."]},{"title":"Equal degree","explanation":"Use as plus the base adjective plus as for equality. Spelling may change in comparative and superlative forms.","examples":["The two boxes are as heavy as each other.","big → bigger → biggest"]}],"tips":["Read the full context before choosing.","Check the explanation, including after a correct answer.","A passing practice session is useful feedback, not a language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v1","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-comparisons","pcc-esol"],"assessment":"Practice only; levels are approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["A comparative compares one thing with another; a superlative places one member at an extreme within a group. Equal comparisons use as ... as. First choose the kind of comparison, then form the adjective correctly. The adjective does not agree with a noun’s number."],"rules":[{"title":"Comparing two","explanation":"Many short adjectives add -er; longer adjectives often use more. Introduce the second item with than. Avoid adding more to an -er comparative.","examples":["This route is shorter than that one.","The new seat is more comfortable.","This route is **shorter than** the coastal road."],"pattern":"small → small**er** → small**est**","paragraphs":["Many short adjectives take -er and -est. Spelling may change: big → bigger, happy → happier. Many longer adjectives use more and most. Some two-syllable adjectives allow both patterns, so avoid treating every alternative as wrong without checking usage."],"id":"comparatives-and-superlatives-foundation-1","domain":"comparison","referenceIds":["bc-comparisons","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Comparing a group","explanation":"Use the plus a superlative: often -est or most plus the adjective. Good becomes better/best; bad becomes worse/worst.","examples":["This is the safest path.","That was the best result.","The two routes are **as safe as** each other."],"pattern":"interesting → **more** interesting → **most** interesting","paragraphs":["Good → better → best and bad → worse → worst are irregular. Farther and further have overlapping uses, with further also meaning additional. Do not put more before an adjective that already has the ordinary comparative ending: more taller is not standard."],"id":"comparatives-and-superlatives-foundation-2","domain":"comparison","referenceIds":["bc-comparisons","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Equal degree","explanation":"Use as plus the base adjective plus as for equality. Spelling may change in comparative and superlative forms.","examples":["The two boxes are as heavy as each other.","big → bigger → biggest","This is **the most direct** route of the three."],"pattern":"**as tall as** · **taller than** · **the tallest in** the group","paragraphs":["Use than to introduce the comparison target after a comparative. Use as on both sides of the adjective for equality. Superlatives usually take the, but possessives can replace it: my best friend. A superlative needs an understood comparison group."],"id":"comparatives-and-superlatives-foundation-3","domain":"comparison","referenceIds":["bc-comparisons","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"title":"Contrasts and edge cases","explanation":"Much, far and a little modify comparatives: much faster, a little slower. Very faster is not the ordinary pattern. A comparative can be used without an explicit than phrase if the reference is understood: This one is better. Not as ... as expresses inequality without a comparative ending.","examples":["This route is **shorter than** the coastal road.","The two routes are **as safe as** each other.","This is **the most direct** route of the three."],"id":"comparatives-and-superlatives-foundation-4","domain":"comparison","referenceIds":["bc-comparisons","pcc-esol"],"readingVersion":"foundations-2026-09-v1"},{"domain":"comparison","id":"comparative-clauses-ellipsis","title":"Comparative clauses and omitted material","explanation":"Than and as can introduce clauses in which repeated material is omitted. A remaining pronoun may have different forms depending on whether it is interpreted as part of a clause or as a complement in a shorter construction. Expanding the comparison makes the roles clear and can remove ambiguity.","pattern":"She is taller **than I am** / **than me**.","examples":["He likes football more than **I do**.","She helped Alex more than **she helped me**."],"commonMistakes":["He likes her more than me can compare the people he likes or the people who like her. Expand the clause to state which comparison you mean."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"comparison","id":"less-fewer-superlative-scope","title":"Less, fewer and the comparison set","explanation":"Fewer normally modifies plural count nouns; less normally modifies non-count quantities. Less also appears with measurements and fixed numerical expressions. A superlative selects an extreme within an understood group, so the comparison set must be clear. Comparative forms can compare two members or two states of the same thing.","pattern":"**fewer mistakes** / **less work**","examples":["It took **less than ten minutes**.","She is **the youngest in the team**."],"commonMistakes":["Fewer is useful for separate countable items, but a blanket ban on less before every number misrepresents ordinary measurement expressions."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["small → small**er** → small**est**","interesting → **more** interesting → **most** interesting","**as tall as** · **taller than** · **the tallest in** the group"],"readingVersion":"core-2026-09-v4"},"stage":"2 · Everyday descriptions","prerequisites":["ed-ing-adjectives"],"readingReferenceIds":["bc-comparisons","pcc-esol","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='comparatives-and-superlatives'
